package com.primehr.rewardsrecognition.api;
import com.primehr.rewardsrecognition.api.RrAwardDtos.*;import com.primehr.rewardsrecognition.application.RrAwardService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/rewards-recognition") public class RrAwardController{private final RrAwardService service;private final RrAwardPermissionGuard permission;private final AgencyScopeResolver agency;public RrAwardController(RrAwardService service,RrAwardPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}
 @GetMapping("/awards")public List<AwardResponse>awards(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t){return service.awards(agency(a),actor(a),permission.require(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.ACCESS,t));}
 @GetMapping("/awards/{id}")public AwardResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){return service.get(agency(a),id,actor(a),permission.require(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.ACCESS,t));}
 @PostMapping("/evaluation-cases/{id}/award")@ResponseStatus(HttpStatus.CREATED)public AwardResponse confer(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ConferInput in){permission.requireAgency(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.FINALIZE,t);return service.confer(agency(a),id,in,actor(a),c);}
 @PostMapping("/awards/{id}/corrections")@ResponseStatus(HttpStatus.CREATED)public AwardResponse correct(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody CorrectInput in){permission.requireAgency(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.APPROVE,t);return service.correct(agency(a),id,in,actor(a),c);}
 @PostMapping("/awards/{id}/revocations")@ResponseStatus(HttpStatus.CREATED)public AwardResponse revoke(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody RevokeInput in){permission.requireAgency(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.APPROVE,t);return service.revoke(agency(a),id,in,actor(a),c);}
 @PostMapping("/awards/{id}/incentives")@ResponseStatus(HttpStatus.CREATED)public AwardResponse incentive(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IncentiveInput in){var scope=permission.require(RrAwardPermissionGuard.FULFILLMENT,PrimeHrAction.ADD,t);return service.authorizeIncentive(agency(a),id,in,actor(a),scope,c);}
 @PostMapping("/awards/{id}/incentives/{authorizationId}/fulfillment")@ResponseStatus(HttpStatus.CREATED)public AwardResponse fulfillment(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String authorizationId,@Valid@RequestBody FulfillmentInput in){var scope=permission.require(RrAwardPermissionGuard.FULFILLMENT,PrimeHrAction.APPROVE,t);return service.recordFulfillment(agency(a),id,authorizationId,in,actor(a),scope,c);}
 @PostMapping("/awards/{id}/hap-events")@ResponseStatus(HttpStatus.CREATED)public AwardResponse hap(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody HapInput in){permission.requireAgency(RrEvaluationPermissionGuard.AWARD,PrimeHrAction.PUBLISH,t);return service.recordHap(agency(a),id,in,actor(a),c);}
 @GetMapping("/reports/annual-register")public AnnualRegisterResponse annual(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam int year){permission.requireAgency(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,t);return service.annualRegister(agency(a),year);}
}
